const getAllPosts = `-- name: GetAllPosts :many
SELECT 
    p.post_id,
    p.user_id,
    p.title,
    p.content,
    p.photo,
    p.video,
    p.created_at,
    p.updated_at,
    u.username AS user_name,
    u.avatar AS user_avatar,
    COALESCE(l.likes_count, 0) AS like_count,
    COALESCE(v.views_count, 0) AS views_count,
    COALESCE(c.comments_count, 0) AS comment_count,
    EXISTS (
        SELECT 1 FROM likes 
        WHERE likes.post_id = p.post_id 
        AND likes.user_id = $1
    ) AS liked_by_user,
    COUNT(*) OVER() AS total_count
FROM posts p
LEFT JOIN users u ON p.user_id = u.user_id
LEFT JOIN (
    SELECT post_id, COUNT(*) AS likes_count 
    FROM likes 
    GROUP BY post_id
) l ON p.post_id = l.post_id
LEFT JOIN (
    SELECT post_id, COUNT(*) AS views_count 
    FROM views 
    GROUP BY post_id
) v ON p.post_id = v.post_id
LEFT JOIN (
    SELECT post_id::uuid, COUNT(*) AS comments_count 
    FROM comments 
    WHERE visible = TRUE
    GROUP BY post_id
) c ON p.post_id = c.post_id
WHERE (p.title ILIKE '%' || $2 || '%' OR $2 IS NULL)
AND (p.content ILIKE '%' || $3 || '%' OR $3 IS NULL)
ORDER BY 
    CASE 
        WHEN $4 = 'likes' THEN COALESCE(l.likes_count, 0)
        WHEN $4 = 'comments' THEN COALESCE(c.comments_count, 0)
        ELSE 0
    END DESC,
    p.created_at DESC
LIMIT $6
OFFSET $5
`

